#define LOG 20

static int n, q;
static int parent[MAXN], depth[MAXN];
static int up[LOG][MAXN];

static int firstChild[MAXN], nextSibling[MAXN];
static int subtreeSize[MAXN], heavy[MAXN];
static int chainHead[MAXN], pos[MAXN], nodeAtPos[MAXN];

static int segSum[4 * MAXN];
static unsigned char lazyZero[4 * MAXN];

static int readInt(void) {
    int c = getchar_unlocked();
    while (c <= ' ' && c != EOF) c = getchar_unlocked();

    int value = 0;
    while (c > ' ') {
        value = value * 10 + c - '0';
        c = getchar_unlocked();
    }
    return value;
}

static void applyZero(int node) {
    segSum[node] = 0;
    lazyZero[node] = 1;
}

static void pushDown(int node) {
    if (lazyZero[node]) {
        applyZero(node * 2);
        applyZero(node * 2 + 1);
        lazyZero[node] = 0;
    }
}

static void clearRange(int node, int left, int right, int ql, int qr) {
    if (ql <= left && right <= qr) {
        applyZero(node);
        return;
    }

    pushDown(node);
    int mid = (left + right) / 2;
    if (ql <= mid) clearRange(node * 2, left, mid, ql, qr);
    if (qr > mid) clearRange(node * 2 + 1, mid + 1, right, ql, qr);
    segSum[node] = segSum[node * 2] + segSum[node * 2 + 1];
}

static void activatePoint(int node, int left, int right, int at) {
    if (left == right) {
        segSum[node] = 1;
        lazyZero[node] = 0;
        return;
    }

    pushDown(node);
    int mid = (left + right) / 2;
    if (at <= mid) activatePoint(node * 2, left, mid, at);
    else activatePoint(node * 2 + 1, mid + 1, right, at);
    segSum[node] = segSum[node * 2] + segSum[node * 2 + 1];
}

static int rangeSum(int node, int left, int right, int ql, int qr) {
    if (ql <= left && right <= qr) return segSum[node];

    pushDown(node);
    int mid = (left + right) / 2;
    int result = 0;
    if (ql <= mid) result += rangeSum(node * 2, left, mid, ql, qr);
    if (qr > mid) result += rangeSum(node * 2 + 1, mid + 1, right, ql, qr);
    return result;
}

static int kthOne(int node, int left, int right, int k) {
    if (left == right) return left;

    pushDown(node);
    int mid = (left + right) / 2;
    if (segSum[node * 2] >= k)
        return kthOne(node * 2, left, mid, k);
    return kthOne(node * 2 + 1, mid + 1, right, k - segSum[node * 2]);
}

static int ancestor(int v, int k) {
    for (int bit = 0; bit < LOG; bit++) {
        if (k & (1 << bit)) v = up[bit][v];
    }
    return v;
}

