    int count = rangeSum(1, 1, n, left, right);
    if (count == 0) return 0;

    int before = rangeSum(1, 1, n, 1, left - 1);
    *topmost = nodeAtPos[kthOne(1, 1, n, before + 1)];

    if (*remaining <= count) {
        int rank = before + count - *remaining + 1;
        return nodeAtPos[kthOne(1, 1, n, rank)];
    }

    *remaining -= count;
    return 0;
}

