    int remaining = k;
    int topmost = 0;
    int u = parent[v];

    while (u != 0 && chainHead[u] != chainHead[1]) {
        int result = processSegment(pos[chainHead[u]], pos[u],
                                    &remaining, &topmost);
        if (result) return result;
        u = parent[chainHead[u]];
    }

    if (u != 0) {
        int result = processSegment(pos[1], pos[u], &remaining, &topmost);
        if (result) return result;
    }

    int base = topmost ? topmost : v;
    return ancestor(base, remaining);
}

