        up[0][i] = parent[i];
        subtreeSize[i] = 1;
        heavy[i] = 0;
    }
    for (int bit = 1; bit < LOG; bit++) {
        for (int i = 1; i <= n; i++)
            up[bit][i] = up[bit - 1][up[bit - 1][i]];
    }

    for (int i = n; i >= 2; i--) {
        int p = parent[i];
        subtreeSize[p] += subtreeSize[i];
        if (heavy[p] == 0 || subtreeSize[i] > subtreeSize[heavy[p]])
            heavy[p] = i;
    }

    int stackNode[MAXN], stackHead[MAXN];
    int stackSize = 0, timer = 0;
    stackNode[stackSize] = 1;
    stackHead[stackSize++] = 1;

    while (stackSize > 0) {
        int start = stackNode[--stackSize];
        int h = stackHead[stackSize];

        for (int v = start; v != 0; v = heavy[v]) {
            chainHead[v] = h;
            pos[v] = ++timer;
            nodeAtPos[timer] = v;

            for (int c = firstChild[v]; c != 0; c = nextSibling[c]) {
                if (c != heavy[v]) {
                    stackNode[stackSize] = c;
                    stackHead[stackSize++] = c;
                }
            }
        }
    }

    q = readInt();
    for (int i = 0; i < q; i++) {
        int type = readInt();
        if (type == 1) {
            int v = readInt();
            int k = readInt();
            printf("%d\n", answerQuery(v, k));
